import{_ as a,o as i,c as s,ai as t}from"./chunks/framework.Ci0kozOl.js";const m=JSON.parse('{"title":"Creating a New User in UnoPim via the Command Line","description":"","frontmatter":{},"headers":[],"relativePath":"0.1/introduction/creating-newuser.md","filePath":"0.1/introduction/creating-newuser.md","lastUpdated":1779432347000}'),n={name:"0.1/introduction/creating-newuser.md"};function o(r,e,l,d,c,p){return i(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="creating-a-new-user-in-unopim-via-the-command-line" tabindex="-1">Creating a New User in UnoPim via the Command Line <a class="header-anchor" href="#creating-a-new-user-in-unopim-via-the-command-line" aria-label="Permalink to &quot;Creating a New User in UnoPim via the Command Line&quot;">​</a></h1><p>Use the following command structure to create a new user in UnoPim:</p><p><strong><code>php artisan unopim:user:create --name=&quot;username&quot; --email=&quot;useremail&quot; --password=&quot;userpassword&quot; --ui_locale=&quot;locale_code&quot; --timezone=&quot;timezone&quot; --admin</code></strong></p><h2 id="command-parameters-explained" tabindex="-1">Command Parameters Explained <a class="header-anchor" href="#command-parameters-explained" aria-label="Permalink to &quot;Command Parameters Explained&quot;">​</a></h2><ul><li><strong><code>--name</code></strong>: Full name of the user, displayed across the UnoPim interface.</li><li><strong><code>--email</code></strong>: User&#39;s email address, used for login and notifications.</li><li><strong><code>--password</code></strong>: A strong password for the account. Follow secure password practices.</li><li><strong><code>--ui_locale</code></strong>: User interface language code (e.g., <code>en_US</code> for English, <code>fr_FR</code> for French).</li><li><strong><code>--timezone</code></strong>: User&#39;s timezone (e.g., <code>UTC</code>, <code>America/New_York</code>, <code>Asia/Kolkata</code>) for accurate timestamps.</li><li><strong><code>--admin</code></strong> <em>(optional)</em>: Optional. This flag, if included, grants the user admin privileges. Admin users have full access to all features and settings in UnoPim, making it crucial to assign this role carefully. If this flag is not added, a custom role is assigned by default (if anyone exists). Otherwise, a default custom role with dashboard-only permissions is created and assigned to the user.</li></ul><h2 id="example-usage" tabindex="-1">Example Usage <a class="header-anchor" href="#example-usage" aria-label="Permalink to &quot;Example Usage&quot;">​</a></h2><p>To create a user with the following details:</p><ul><li><strong>Name</strong>: John Doe</li><li><strong>Email</strong>: <a href="mailto:johndoe@example.com" target="_blank" rel="noreferrer">johndoe@example.com</a></li><li><strong>Password</strong>: securepassword123</li><li><strong>Locale</strong>: English (<code>en_US</code>)</li><li><strong>Timezone</strong>: America/New_York</li><li><strong>Admin Privileges</strong>: -- admin</li></ul><p>Run the command:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> unopim:user:create</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;John Doe&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --email=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;johndoe@example.com&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --password=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;securepassword123&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ui_locale=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;en_US&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --timezone=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;America/New_York&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --admin</span></span></code></pre></div><p>This will create a new user with the specified details and assign admin privileges.</p><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ol><li><p><strong>Secure Credentials</strong>:<br> Ensure strong, unique passwords for each user to prevent unauthorized access.</p></li><li><p><strong>Admin Access</strong>:<br> Only assign admin privileges to trusted individuals as they have unrestricted access to the system.</p></li><li><p><strong>Locale and Timezone</strong>:<br> Setting the appropriate locale and timezone helps improve user experience and ensures accurate logging.</p></li></ol>',13)])])}const u=a(n,[["render",o]]);export{m as __pageData,u as default};
